      "stage": 3,
      "description": "前沿拓展阶段：跨学科研究能力构建",
      "actions": [
        "研读《Cell》《Nature Cancer》最新综述（如mRNA疫苗设计、液体活检技术），建立个人文献笔记库",
        "加入癌症生物信息学开源项目（如cBioPortal），参与癌症基因组图谱（TCGA）协作分析",
        "设计个人研究提案：结合生物信息学工具与临床试验设计原则，探索新型癌症早诊标志物"
      ]
    }
  ],
  "learning_solutions": [
    {
      "bioinformatics_support": {
        "resource": "癌症基因组图谱（TCGA）官方教程",
        "activity": "使用cBioPortal完成结直肠癌基因表达数据可视化分析",
        "deliverable": "生成包含差异表达基因热力图的分析报告"
      },
      "clinical_trial_design": {
        "resource": "《临床试验设计：统计方法学导论》（Chaudhary & Shadish）",
        "activity": "设计一个针对PD-1抑制剂耐药性的虚拟III期试验（含样本量计算与终点设定）",
        "deliverable": "提交含流程图与统计假设检验的试验设计文档"
      },
      "research_writing": {
        "resource": "《科学论文写作指南》（Zhang & Nitkey）",
        "activity": "将TCGA项目分析结果改写为结构化摘要（背景-方法-结果-结论）",
        "deliverable": "符合Nature风格的三段式摘要模板"
      }
    }
  ]
}
```

